import { Swap as SwapPrimitive, useSwap, useSwapContext } from '@ark-ui/solid/swap';
import { clsx } from 'clsx';
import type { ComponentProps } from 'solid-js';
import { splitProps } from 'solid-js';
import styles from './Swap.module.css';

type SwapAnimation = 'fade' | 'scale' | 'rotate' | 'flip' | (string & {});

type SwapProps = ComponentProps<typeof SwapPrimitive.Root> & {
  animation?: SwapAnimation;
};

type SwapRootProviderProps = ComponentProps<typeof SwapPrimitive.RootProvider> & {
  animation?: SwapAnimation;
};

function Swap(props: SwapProps) {
  const [local, others] = splitProps(props, ['animation', 'class']);

  return (
    <SwapPrimitive.Root
      class={clsx(styles.root, local.class)}
      {...others}
      data-animation={local.animation ?? 'scale'}
      data-slot="swap-root"
    />
  );
}

function SwapRootProvider(props: SwapRootProviderProps) {
  const [local, others] = splitProps(props, ['animation', 'class']);

  return (
    <SwapPrimitive.RootProvider
      class={clsx(styles.root, local.class)}
      {...others}
      data-animation={local.animation ?? 'scale'}
      data-slot="swap-root-provider"
    />
  );
}

function SwapIndicator(props: ComponentProps<typeof SwapPrimitive.Indicator>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <SwapPrimitive.Indicator
      class={clsx(styles.indicator, local.class)}
      {...others}
      data-slot="swap-indicator"
    />
  );
}

export { Swap, SwapIndicator, SwapRootProvider, useSwap, useSwapContext, type SwapAnimation };

@layer moduix.components {
  .root {
    place-items: center;
    vertical-align: middle;

    &[data-animation='flip'] {
      perspective: 24rem;
    }

    &[data-animation='fade'] > .indicator[data-state='open'] {
      animation: swap-fade-enter var(--moduix-swap-transition, var(--moduix-transition-slow));
    }

    &[data-animation='fade'] > .indicator[data-state='closed'] {
      animation: swap-fade-exit var(--moduix-swap-transition, var(--moduix-transition-slow));
    }

    &[data-animation='scale'] > .indicator[data-state='open'] {
      animation: swap-scale-enter var(--moduix-swap-transition, var(--moduix-transition-slow));
    }

    &[data-animation='scale'] > .indicator[data-state='closed'] {
      animation: swap-scale-exit var(--moduix-swap-transition, var(--moduix-transition-slow));
    }

    &[data-animation='rotate'] > .indicator[data-state='open'] {
      animation: swap-rotate-enter var(--moduix-swap-transition, var(--moduix-transition-slow));
    }

    &[data-animation='rotate'] > .indicator[data-state='closed'] {
      animation: swap-rotate-exit var(--moduix-swap-transition, var(--moduix-transition-slow));
    }

    &[data-animation='flip'] > .indicator {
      backface-visibility: hidden;
    }

    &[data-animation='flip'] > .indicator[data-state='open'] {
      animation: swap-flip-enter var(--moduix-swap-transition, var(--moduix-transition-slow));
    }

    &[data-animation='flip'] > .indicator[data-state='closed'] {
      animation: swap-flip-exit var(--moduix-swap-transition, var(--moduix-transition-slow));
    }
  }

  .indicator {
    align-items: center;
    justify-content: center;
  }

  @media (prefers-reduced-motion: reduce) {
    .root[data-animation] > .indicator[data-state] {
      animation: none;
    }
  }

  @keyframes swap-fade-enter {
    from {
      opacity: 0;
    }
  }

  @keyframes swap-fade-exit {
    to {
      opacity: 0;
    }
  }

  @keyframes swap-scale-enter {
    from {
      opacity: 0;
      transform: scale(0.5);
    }
  }

  @keyframes swap-scale-exit {
    to {
      opacity: 0;
      transform: scale(0.5);
    }
  }

  @keyframes swap-rotate-enter {
    from {
      opacity: 0;
      transform: rotate(-180deg);
    }
  }

  @keyframes swap-rotate-exit {
    to {
      opacity: 0;
      transform: rotate(180deg);
    }
  }

  @keyframes swap-flip-enter {
    from {
      opacity: 0;
      transform: rotateY(-180deg);
    }
  }

  @keyframes swap-flip-exit {
    to {
      opacity: 0;
      transform: rotateY(180deg);
    }
  }
}
